package run.ikaros.finance; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.NotFoundException; @Service public class FinanceClassificationService{private final LedgerRepository ledgers;private final FinanceCategoryRepository categories;private final FinanceTagRepository tags;public FinanceClassificationService(LedgerRepository l,FinanceCategoryRepository c,FinanceTagRepository t){ledgers=l;categories=c;tags=t;}public Mono<CategoryView> createCategory(UUID a,UUID l,CreateCategoryRequest q){return own(a,l).flatMap(x->categories.save(new FinanceCategoryEntity(null,l,a,q.parentId(),q.name().trim(),q.kind()==null?"EXPENSE":q.kind(),false,null))).map(this::category);}public Flux<CategoryView> categories(UUID a,UUID l){return own(a,l).flatMapMany(x->categories.findAllByLedgerIdAndOwnerIdOrderByNameAsc(l,a).map(this::category));}public Mono<TagView> createTag(UUID a,UUID l,CreateTagRequest q){return own(a,l).flatMap(x->tags.save(new FinanceTagEntity(null,l,a,q.name().trim(),null))).map(this::tag);}public Flux<TagView> tags(UUID a,UUID l){return own(a,l).flatMapMany(x->tags.findAllByLedgerIdAndOwnerIdOrderByNameAsc(l,a).map(this::tag));}private Mono<LedgerEntity> own(UUID a,UUID id){return ledgers.findById(id).filter(x->x.ownerId().equals(a)).switchIfEmpty(Mono.error(new NotFoundException("Ledger 不存在或无权访问")));}private CategoryView category(FinanceCategoryEntity x){return new CategoryView(x.id(),x.ledgerId(),x.parentId(),x.name(),x.kind(),x.archived());}private TagView tag(FinanceTagEntity x){return new TagView(x.id(),x.ledgerId(),x.name());}}
